// ============================================================
// SAFETY RISK CHECK
//
// Purpose:
// Check the customer's message for signs of a possible
// hardware safety problem.
//
// Examples:
// - Burning smell
// - Smoke
// - Sparks
// - Electric shock
// - Swollen battery
// - Extreme heat
//
// This check happens using normal code instead of relying
// only on the AI to recognize dangerous situations.
// ============================================================


// ------------------------------------------------------------
// 1. GET THE CUSTOMER MESSAGE
//
// Get the message from the Normalize Chat node.
//
// String() makes sure we are working with text.
//
// toLowerCase() converts everything to lowercase so
// words like "SMOKE", "Smoke", and "smoke" are treated
// the same way.
//
// If there is no message, use an empty string.
// ------------------------------------------------------------

const msg = String(
  $('Normalize Chat').item.json.Message_body || ''
).toLowerCase();


// ------------------------------------------------------------
// 2. DEFINE SAFETY PATTERNS
//
// These are words and text patterns that may indicate
// a dangerous hardware problem.
//
// The /.../ values are Regular Expressions (Regex).
// They allow us to match different ways a customer
// might describe the same safety problem.
// ------------------------------------------------------------

const patterns = [

  // Burning smell
  /burning smell/,
  /burn(ing|t)?\s+smell/,
  /smell.*burn/,

  // Smoke
  /smoke|smoking/,

  // Sparks
  /spark(s|ing|ed)?/,

  // Fire
  /on fire|caught fire|catching fire|\bfire\b/,

  // Electrical shock or electrical arcing
  /electric(al)? shock|shocked me|got shocked|arc(ing|ed)?/,

  // Swollen, leaking, or bulging battery
  /swollen batter|bulging batter|leaking batter|battery.*(swollen|leak|bulg)/,

  // Signs of heat or burn damage
  /melt(ing|ed)?|scorch|charred|burn mark/,

  // Dangerous overheating
  /dangerous(ly)? (hot|overheat)|overheat(ing|ed)?|too hot to touch/,
];


// ------------------------------------------------------------
// 3. DEFAULT TO NO SAFETY RISK
//
// We start with false.
//
// It will only become true if one of the safety patterns
// matches the customer's message.
// ------------------------------------------------------------

let safety_risk = false;


// ------------------------------------------------------------
// 4. CHECK EACH SAFETY PATTERN
//
// Go through the patterns one by one.
//
// p.test(msg) checks if the current pattern can be found
// inside the customer's message.
//
// Once we find a match:
// - safety_risk becomes true
// - break stops the loop because we already know there
//   is a possible safety problem.
// ------------------------------------------------------------

for (const p of patterns) {

  if (p.test(msg)) {
    safety_risk = true;
    break;
  }

}


// ------------------------------------------------------------
// 5. RETURN THE RESULT
//
// Example:
//
// Safe message:
// { "safety_risk": false }
//
// Possible dangerous message:
// { "safety_risk": true }
//
// The next IF node can use this value to decide whether
// normal troubleshooting should continue or the case
// should go through the safety/escalation path.
// ------------------------------------------------------------

return {
  safety_risk
};

// ============================================================
// DECISION VALIDATION
//
// Purpose:
// Check the AI output before the workflow uses it.
//
// We do not want to trust every AI value automatically.
// If the AI gives an unexpected value, we use a safe default.
// ============================================================


// ------------------------------------------------------------
// 1. GET THE AI OUTPUT
//
// The AI result should normally be inside $json.output.
//
// If there is no proper output, use an empty object {}
// so the code does not immediately break.
// ------------------------------------------------------------

const output =
  $json.output && typeof $json.output === "object"
    ? $json.output
    : {};


// ------------------------------------------------------------
// 2. VALUES THAT WE ALLOW
//
// The AI should only use values from these lists.
//
// Example:
// "High" = allowed
// "SUPER HIGH" = not allowed
// ------------------------------------------------------------

const ALLOWED_PRIORITY = [
  "Low",
  "Medium",
  "High"
];

const ALLOWED_BUSINESS_IMPACT = [
  "Low",
  "Medium",
  "High"
];

const ALLOWED_SUPPORT_LEVEL = [
  "L1",
  "L2",
  "ESCALATE",
  "RESOLVED",
  "MORE_INFO"
];

const ALLOWED_CATEGORY = [
  "CPU",
  "Motherboard",
  "RAM",
  "Graphics Card",
  "Power Supply",
  "Storage",
  "Cooling",
  "BIOS / UEFI",
  "Boot Issues",
  "Display",
  "Peripheral Devices",
  "Operating System",
  "Performance",
  "General Hardware Inquiry"
];


// ------------------------------------------------------------
// 3. SIMPLE VALIDATION FUNCTION
//
// This checks if a value is allowed.
//
// If yes:
// return the original value.
//
// If no:
// return the safe default value.
// ------------------------------------------------------------

function validateValue(value, allowedValues, fallback) {

  if (allowedValues.includes(value)) {
    return value;
  }

  return fallback;
}


// ------------------------------------------------------------
// 4. CHECK PRIORITY
//
// If the AI gives Low, Medium, or High,
// we keep it.
//
// Otherwise, use Medium.
// ------------------------------------------------------------

const priority = validateValue(
  output.priority,
  ALLOWED_PRIORITY,
  "Medium"
);


// ------------------------------------------------------------
// 5. CHECK BUSINESS IMPACT
//
// If the AI gives an unexpected value,
// use Low as the default.
// ------------------------------------------------------------

const businessImpact = validateValue(
  output.business_impact,
  ALLOWED_BUSINESS_IMPACT,
  "Low"
);


// ------------------------------------------------------------
// 6. CHECK SUPPORT LEVEL
//
// This is important because the workflow can use this
// to decide what should happen next.
//
// If the AI gives an invalid value,
// use MORE_INFO instead.
// ------------------------------------------------------------

const supportLevel = validateValue(
  output.support_level,
  ALLOWED_SUPPORT_LEVEL,
  "MORE_INFO"
);


// ------------------------------------------------------------
// 7. CHECK CATEGORY
//
// If the AI gives a category that we do not recognize,
// use General Hardware Inquiry.
// ------------------------------------------------------------

const category = validateValue(
  output.category,
  ALLOWED_CATEGORY,
  "General Hardware Inquiry"
);


// ------------------------------------------------------------
// 8. GET THE CUSTOMER REPLY
//
// Make sure the reply is actually text.
//
// trim() simply removes extra spaces from the
// beginning and end.
//
// If there is no proper reply, use an empty string.
// ------------------------------------------------------------

const reply =
  typeof output.reply === "string"
    ? output.reply.trim()
    : "";


// ------------------------------------------------------------
// 9. KEEP TRACK OF INVALID VALUES
//
// This makes debugging easier.
//
// Example:
//
// ["priority", "reply"]
//
// means there was a problem with those two fields.
// ------------------------------------------------------------

const validationErrors = [];

if (!ALLOWED_PRIORITY.includes(output.priority)) {
  validationErrors.push("priority");
}

if (!ALLOWED_BUSINESS_IMPACT.includes(output.business_impact)) {
  validationErrors.push("business_impact");
}

if (!ALLOWED_SUPPORT_LEVEL.includes(output.support_level)) {
  validationErrors.push("support_level");
}

if (!ALLOWED_CATEGORY.includes(output.category)) {
  validationErrors.push("category");
}

if (!reply) {
  validationErrors.push("reply");
}


// ------------------------------------------------------------
// 10. DECIDE IF THE AI OUTPUT CAN BE USED
//
// The two most important things here are:
//
// 1. We need a customer reply.
// 2. We need a valid support level.
//
// If either one is missing or invalid,
// valid becomes false.
// ------------------------------------------------------------

const valid =
  reply !== "" &&
  ALLOWED_SUPPORT_LEVEL.includes(output.support_level);


// ------------------------------------------------------------
// 11. RETURN CLEAN DATA
//
// From this point forward, the next workflow nodes
// should use these checked values instead of using
// the raw AI output directly.
// ------------------------------------------------------------

return {
  valid,

  validation_errors: validationErrors,

  category,
  priority,
  business_impact: businessImpact,
  support_level: supportLevel,

  complaint_detected:
    output.complaint_detected === true,

  safety_risk:
    output.safety_risk === true,

  tool_needed:
    output.tool_needed || "",

  tool_query:
    output.tool_query || "",

  case_update_needed:
    output.case_update_needed === true,

  escalation_required:
    output.escalation_required === true,

  assigned_team:
    output.assigned_team || "AI",

  reply
};

